        // User U's first, genuine full listen of track T at time 0, 45 seconds long: qualifies, no prior play.
        System.out.println("U plays T at t=0 for 45s: " + counter.recordPlay("U", "T", 0, 45));

        // User U replays T at t=60 (only 60s after the last counted play) for 40s: meets duration, but within cooldown.
        System.out.println("U plays T at t=60 for 40s (too soon): " + counter.recordPlay("U", "T", 60, 40));

        // User U replays T at t=200 (200s after the last COUNTED play at t=0, past the 120s cooldown) for 35s: counted.
        System.out.println("U plays T at t=200 for 35s (cooldown passed): " + counter.recordPlay("U", "T", 200, 35));

        // User U skips T at t=250 after only 10 seconds: never counted, regardless of cooldown.
        System.out.println("U plays T at t=250 for 10s (too short): " + counter.recordPlay("U", "T", 250, 10));

        // A different user V plays the same track T at t=5 for 40s: evaluated entirely independently of U.
        System.out.println("V plays T at t=5 for 40s (different user): " + counter.recordPlay("V", "T", 5, 40));

        System.out.println("Total qualifying, billable streams: " + counter.qualifyingStreamCount());
    }
}

// Decides whether a completed listen counts as a billable, royalty-qualifying
// stream: it must meet a minimum listen duration, and must not be a rapid
// repeat of the same track by the same user within an anti-abuse cooldown window.
class StreamCounter {
    private final int minQualifyingSeconds;
    private final long cooldownSeconds;
    private final java.util.Map<String, Long> lastCountedPlayAt = new java.util.HashMap<>(); // "user:track" -> last counted play time
    private int qualifyingStreamCount = 0;

    StreamCounter(int minQualifyingSeconds, long cooldownSeconds) {
        this.minQualifyingSeconds = minQualifyingSeconds;
        this.cooldownSeconds = cooldownSeconds;
    }

    boolean recordPlay(String userId, String trackId, long startedAt, int listenDurationSeconds) {
        if (listenDurationSeconds < minQualifyingSeconds) {
            return false; // too short to ever qualify as a billable stream, regardless of cooldown
        }

        String key = userId + ":" + trackId;
        Long lastCounted = lastCountedPlayAt.get(key);
        if (lastCounted != null && (startedAt - lastCounted) < cooldownSeconds) {
            return false; // meets duration, but too soon after this same user's last counted play of this track
        }

        lastCountedPlayAt.put(key, startedAt); // record this as the new last counted play for this user and track
        qualifyingStreamCount++;
        return true;
    }

    int qualifyingStreamCount() {
        return qualifyingStreamCount;
    }
}

