#include <iostream>
#include <map>
#include <string>
using namespace std;

// Decides whether a completed listen counts as a billable, royalty-qualifying
// stream: it must meet a minimum listen duration, and must not be a rapid
// repeat of the same track by the same user within an anti-abuse cooldown window.
class StreamCounter {
public:
    StreamCounter(int minQualifyingSeconds, long cooldownSeconds)
        : minQualifyingSeconds(minQualifyingSeconds), cooldownSeconds(cooldownSeconds), qualifyingStreamCountValue(0) {}

    bool recordPlay(const string& userId, const string& trackId, long startedAt, int listenDurationSeconds) {
        if (listenDurationSeconds < minQualifyingSeconds) {
            return false; // too short to ever qualify as a billable stream, regardless of cooldown
        }

        string key = userId + ":" + trackId;
        auto it = lastCountedPlayAt.find(key);
        if (it != lastCountedPlayAt.end() && (startedAt - it->second) < cooldownSeconds) {
            return false; // meets duration, but too soon after this same user's last counted play of this track
        }

        lastCountedPlayAt[key] = startedAt; // record this as the new last counted play for this user and track
        qualifyingStreamCountValue++;
        return true;
    }

    int qualifyingStreamCount() {
        return qualifyingStreamCountValue;
    }

private:
    int minQualifyingSeconds;
    long cooldownSeconds;
    map<string, long> lastCountedPlayAt; // "user:track" -> last counted play time
    int qualifyingStreamCountValue;
};

int main() {
    StreamCounter counter(30, 120); // 30s minimum duration, 120s anti-abuse cooldown

    // User U's first, genuine full listen of track T at time 0, 45 seconds long: qualifies, no prior play.
    cout << "U plays T at t=0 for 45s: " << (counter.recordPlay("U", "T", 0, 45) ? "true" : "false") << endl;

    // User U replays T at t=60 (only 60s after the last counted play) for 40s: meets duration, but within cooldown.
    cout << "U plays T at t=60 for 40s (too soon): " << (counter.recordPlay("U", "T", 60, 40) ? "true" : "false") << endl;

    // User U replays T at t=200 (200s after the last COUNTED play at t=0, past the 120s cooldown) for 35s: counted.
    cout << "U plays T at t=200 for 35s (cooldown passed): " << (counter.recordPlay("U", "T", 200, 35) ? "true" : "false") << endl;

    // User U skips T at t=250 after only 10 seconds: never counted, regardless of cooldown.
    cout << "U plays T at t=250 for 10s (too short): " << (counter.recordPlay("U", "T", 250, 10) ? "true" : "false") << endl;

    // A different user V plays the same track T at t=5 for 40s: evaluated entirely independently of U.
    cout << "V plays T at t=5 for 40s (different user): " << (counter.recordPlay("V", "T", 5, 40) ? "true" : "false") << endl;

    cout << "Total qualifying, billable streams: " << counter.qualifyingStreamCount() << endl;

    return 0;
}

